from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path
from typing import Any, Sequence

from . import format as _format
from .ledger import ConflictError, Ledger


EXIT_OK = 0
EXIT_USAGE = 2
EXIT_IO = 3
EXIT_CONFLICT = 4
EXIT_CORRUPTION = 5


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="ledgerlock",
        description="Append-only tamper-evident key/value ledger.",
    )
    sub = parser.add_subparsers(dest="command")
    sub.required = True

    p_verify = sub.add_parser("verify", help="verify the ledger end-to-end")
    p_verify.add_argument("ledger")

    p_snapshot = sub.add_parser("snapshot", help="write a deterministic snapshot to --out")
    p_snapshot.add_argument("ledger")
    p_snapshot.add_argument("--out", required=True)

    p_apply = sub.add_parser("apply", help="apply an atomic batch from --batch to the ledger")
    p_apply.add_argument("ledger")
    p_apply.add_argument("--batch", required=True)

    p_repair = sub.add_parser("repair-tail", help="strip a truncated final line if repairable")
    p_repair.add_argument("ledger")

    return parser


def _snapshot_bytes(state: dict) -> bytes:
    return (
        json.dumps(state, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        + b"\n"
    )


def _read_batch(path: Path) -> list:
    with open(path, "rb") as f:
        data = f.read()
    obj = json.loads(data.decode("utf-8"))
    if not isinstance(obj, list):
        raise ValueError("batch file must contain a JSON array")
    return obj


def _cmd_verify(ledger_path: Path) -> int:
    ledger = Ledger(ledger_path)
    verdict = ledger.verify()
    if not verdict["ok"]:
        sys.stderr.write(
            f"verify corrupt: first_bad_index={verdict.get('first_bad_index')}\n"
        )
        return EXIT_CORRUPTION
    sys.stderr.write("verify ok\n")
    return EXIT_OK


def _cmd_snapshot(ledger_path: Path, out_path: Path) -> int:
    ledger = Ledger(ledger_path)
    state = ledger.snapshot()
    out_path.parent.mkdir(parents=True, exist_ok=True)
    payload = _snapshot_bytes(state)
    with open(out_path, "wb") as f:
        f.write(payload)
        f.flush()
        os.fsync(f.fileno())
    sys.stderr.write(f"snapshot wrote {out_path}\n")
    return EXIT_OK


def _cmd_apply(ledger_path: Path, batch_path: Path) -> int:
    raw_ops = _read_batch(batch_path)
    ops = []
    for item in raw_ops:
        if not isinstance(item, list):
            raise ValueError("batch elements must be arrays")
        ops.append(tuple(item))
    ledger = Ledger(ledger_path)
    results = ledger.apply_batch(ops)
    appended = sum(1 for r in results if r.get("committed"))
    sys.stderr.write(f"apply appended {appended} lines\n")
    return EXIT_OK


def _cmd_repair(ledger_path: Path) -> int:
    ledger = Ledger(ledger_path)
    verdict = ledger.repair_tail()
    if verdict.get("ok") and verdict.get("repaired"):
        sys.stderr.write(f"repair-tail removed 1 truncated line\n")
        return EXIT_OK
    if verdict.get("ok") and not verdict.get("repaired"):
        sys.stderr.write("repair-tail no-op: chain clean\n")
        return EXIT_OK
    sys.stderr.write(
        f"repair-tail corrupt: first_bad_index={verdict.get('first_bad_index')}\n"
    )
    return EXIT_CORRUPTION


def _exit_for_exception(exc: BaseException) -> int:
    if isinstance(exc, ConflictError):
        idx = "" if exc.batch_index is None else f" batch_index={exc.batch_index}"
        sys.stderr.write(f"conflict on key {exc.key!r}: rid {exc.incoming_rid!r} != committed {exc.committed_rid!r}{idx}\n")
        return EXIT_CONFLICT
    if isinstance(exc, FileNotFoundError):
        sys.stderr.write(f"io error: file not found: {exc}\n")
        return EXIT_IO
    if isinstance(exc, (PermissionError, IsADirectoryError, NotADirectoryError)):
        sys.stderr.write(f"io error: {exc}\n")
        return EXIT_IO
    if isinstance(exc, OSError):
        sys.stderr.write(f"io error: {exc}\n")
        return EXIT_IO
    if isinstance(exc, (ValueError, TypeError)):
        sys.stderr.write(f"usage error: {exc}\n")
        return EXIT_USAGE
    sys.stderr.write(f"unexpected error: {exc}\n")
    return EXIT_USAGE


def main(argv: Sequence[str] | None = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else 2
        if code not in (0, 2):
            return EXIT_USAGE
        return code if code == 0 else EXIT_USAGE

    try:
        if args.command == "verify":
            return _cmd_verify(Path(args.ledger))
        if args.command == "snapshot":
            return _cmd_snapshot(Path(args.ledger), Path(args.out))
        if args.command == "apply":
            return _cmd_apply(Path(args.ledger), Path(args.batch))
        if args.command == "repair-tail":
            return _cmd_repair(Path(args.ledger))
    except SystemExit:
        raise
    except BaseException as exc:
        return _exit_for_exception(exc)

    sys.stderr.write("unknown subcommand\n")
    return EXIT_USAGE


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import json
import os
import threading
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Iterator, List, Optional, Sequence, Tuple, Union

from . import format, store


class ConflictError(Exception):
    def __init__(
        self,
        key: str,
        incoming_rid: str,
        committed_rid: str,
        batch_index: Optional[int] = None,
    ) -> None:
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        idx = "" if batch_index is None else f" (batch_index={batch_index})"
        super().__init__(
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"!= committed rid {committed_rid!r}{idx}"
        )


Op = str
Key = str
Value = Any
Rid = str
Ts = int

PutTuple = Tuple[Op, Key, Value, Rid, Ts]
DeleteTuple = Tuple[Op, Key, Rid, Ts]
MutationTuple = Union[PutTuple, DeleteTuple]

AppendResult = dict


def _line_bytes(line: dict) -> bytes:
    return format.canonical_bytes(line) + b"\n"


def _strip_hash_fields(line: dict) -> dict:
    out = {}
    for k, v in line.items():
        if k == "hash" or k == "prev_hash":
            continue
        out[k] = v
    return out


def _parse_and_strip(raw: bytes) -> dict:
    obj = json.loads(raw.decode("utf-8"))
    return obj


class Ledger:
    def __init__(self, path: Path | str) -> None:
        self._path = Path(path)
        self._lock = threading.Lock()
        self._committed: dict[str, dict] = {}
        self._tail_hash: str = format.GENESIS
        self._load_from_disk()

    @property
    def path(self) -> Path:
        return self._path

    def _load_from_disk(self) -> None:
        try:
            lines = store.read_lines(self._path)
        except FileNotFoundError:
            return
        prev_hash = "GENESIS"
        committed: dict[str, dict] = {}
        for raw in lines:
            try:
                obj = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                break
            stripped = _strip_hash_fields(obj)
            expected = format.line_hash(prev_hash, stripped)
            if obj.get("hash") != expected:
                prev_hash = obj.get("hash", prev_hash)
                continue
            prev_hash = obj["hash"]
            nfc_key = obj["key"]
            committed[nfc_key] = obj
        self._committed = committed
        self._tail_hash = prev_hash

    def _append_line_locked(self, line: dict) -> None:
        line["prev_hash"] = self._tail_hash
        stripped = _strip_hash_fields(line)
        line["hash"] = format.line_hash(self._tail_hash, stripped)
        payload = _line_bytes(line)
        parent = self._path.parent
        parent.mkdir(parents=True, exist_ok=True)
        with open(self._path, "ab") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        self._tail_hash = line["hash"]
        self._committed[line["key"]] = line

    def append(self, op: MutationTuple) -> AppendResult:
        op_name = op[0]
        if op_name == "put":
            _, key, value, rid, ts = op
            nfc_key = format.normalize_key(key)
            if nfc_key == "":
                raise ValueError("empty key after NFC normalization")
        elif op_name == "delete":
            _, key, rid, ts = op
            nfc_key = format.normalize_key(key)
            if nfc_key == "":
                raise ValueError("empty key after NFC normalization")
        else:
            raise ValueError(f"unknown op {op_name!r}")

        with self._lock:
            existing = self._committed.get(nfc_key)
            if existing is not None:
                committed_rid = existing.get("id", "")
                if committed_rid == rid:
                    return {
                        "line": dict(existing),
                        "replayed": True,
                        "committed": False,
                    }
                raise ConflictError(
                    key=nfc_key,
                    incoming_rid=rid,
                    committed_rid=committed_rid,
                    batch_index=None,
                )
            if op_name == "put":
                line = {
                    "op": "put",
                    "key": nfc_key,
                    "value": value,
                    "ts": ts,
                    "id": rid,
                }
            else:
                line = {
                    "op": "delete",
                    "key": nfc_key,
                    "ts": ts,
                    "id": rid,
                }
            self._append_line_locked(line)
            return {"line": dict(line), "replayed": False, "committed": True}

    def apply_batch(self, ops: Sequence[MutationTuple]) -> List[AppendResult]:
        parsed: List[tuple] = []
        for idx, op in enumerate(ops):
            op_name = op[0]
            if op_name == "put":
                _, key, value, rid, ts = op
                nfc_key = format.normalize_key(key)
                if nfc_key == "":
                    raise ValueError("empty key after NFC normalization")
                parsed.append((idx, nfc_key, rid, "put", (op_name, nfc_key, value, rid, ts)))
            elif op_name == "delete":
                _, key, rid, ts = op
                nfc_key = format.normalize_key(key)
                if nfc_key == "":
                    raise ValueError("empty key after NFC normalization")
                parsed.append((idx, nfc_key, rid, "delete", (op_name, nfc_key, rid, ts)))
            else:
                raise ValueError(f"unknown op {op_name!r}")

        with self._lock:
            committed_view = dict(self._committed)
            per_index_results: List[Optional[AppendResult]] = [None] * len(parsed)
            new_lines: List[dict] = []
            next_tail_hash = self._tail_hash
            for idx, nfc_key, rid, op_kind, normalized in parsed:
                existing = committed_view.get(nfc_key)
                if existing is not None:
                    committed_rid = existing.get("id", "")
                    if committed_rid == rid:
                        per_index_results[idx] = {
                            "line": dict(existing),
                            "replayed": True,
                            "committed": False,
                        }
                        continue
                    raise ConflictError(
                        key=nfc_key,
                        incoming_rid=rid,
                        committed_rid=committed_rid,
                        batch_index=idx,
                    )
                if op_kind == "put":
                    line = {
                        "op": "put",
                        "key": nfc_key,
                        "value": normalized[2],
                        "ts": normalized[4],
                        "id": rid,
                    }
                else:
                    line = {
                        "op": "delete",
                        "key": nfc_key,
                        "ts": normalized[3],
                        "id": rid,
                    }
                line["prev_hash"] = next_tail_hash
                stripped = _strip_hash_fields(line)
                line["hash"] = format.line_hash(next_tail_hash, stripped)
                committed_view[nfc_key] = line
                new_lines.append(line)
                per_index_results[idx] = {
                    "line": dict(line),
                    "replayed": False,
                    "committed": True,
                }
                next_tail_hash = line["hash"]

            if new_lines:
                self._write_atomic_with_lines(new_lines)
                self._committed = committed_view
                self._tail_hash = next_tail_hash

            return [r for r in per_index_results if r is not None]

    def _write_atomic_with_lines(self, new_lines: List[dict]) -> None:
        try:
            existing = store.read_lines(self._path)
        except FileNotFoundError:
            existing = []
        all_lines: List[bytes] = list(existing)
        for line in new_lines:
            all_lines.append(_line_bytes(line))
        store.write_atomic(self._path, all_lines)

    def verify(self) -> dict:
        try:
            lines = store.read_lines(self._path)
        except FileNotFoundError:
            raise
        prev = "GENESIS"
        for i, raw in enumerate(lines):
            try:
                obj = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {"ok": False, "first_bad_index": i}
            stripped = _strip_hash_fields(obj)
            expected = format.line_hash(prev, stripped)
            if obj.get("prev_hash") != prev or obj.get("hash") != expected:
                return {"ok": False, "first_bad_index": i}
            prev = obj["hash"]
        return {"ok": True, "first_bad_index": None}

    def snapshot(self) -> dict:
        try:
            lines = store.read_lines(self._path)
        except FileNotFoundError:
            return {}
        state: dict[str, Any] = {}
        for raw in lines:
            obj = json.loads(raw.decode("utf-8"))
            key = obj["key"]
            op = obj["op"]
            if op == "put":
                state[key] = obj.get("value")
            elif op == "delete":
                state.pop(key, None)
        ordered_keys = sorted(state.keys())
        ordered: dict[str, Any] = {}
        for k in ordered_keys:
            ordered[k] = state[k]
        return ordered

    def repair_tail(self) -> dict:
        try:
            raw_bytes = self._path.read_bytes()
        except FileNotFoundError:
            raise
        if raw_bytes == b"":
            verdict = self.verify()
            if verdict["ok"]:
                return {"repaired": False, "ok": True, "first_bad_index": None}
            return {"repaired": False, **verdict}

        lines = raw_bytes.split(b"\n")
        if lines and lines[-1] == b"":
            lines = lines[:-1]

        verdict = self._verify_lines(lines)
        if verdict["ok"]:
            return {"repaired": False, "ok": True, "first_bad_index": None}

        first_bad = verdict["first_bad_index"]
        if first_bad is None or first_bad != len(lines) - 1:
            return {"repaired": False, **verdict}

        try:
            json.loads(lines[-1].decode("utf-8"))
            last_parses = True
        except (UnicodeDecodeError, json.JSONDecodeError):
            last_parses = False

        if not last_parses:
            trimmed = lines[:-1]
            new_verdict = self._verify_lines(trimmed)
            if new_verdict["ok"]:
                rebuilt = b"\n".join(trimmed) + b"\n"
                store.write_atomic(self._path, trimmed)
                self._load_from_disk()
                return {"repaired": True, "ok": True, "first_bad_index": None, "removed": first_bad}
            return {"repaired": False, **new_verdict}

        return {"repaired": False, **verdict}

    def _verify_lines(self, lines: List[bytes]) -> dict:
        prev = "GENESIS"
        for i, raw in enumerate(lines):
            try:
                obj = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {"ok": False, "first_bad_index": i}
            stripped = _strip_hash_fields(obj)
            expected = format.line_hash(prev, stripped)
            if obj.get("prev_hash") != prev or obj.get("hash") != expected:
                return {"ok": False, "first_bad_index": i}
            prev = obj["hash"]
        return {"ok": True, "first_bad_index": None}

    def close(self) -> None:
        pass

    def __enter__(self) -> "Ledger":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

