from __future__ import annotations

import hashlib
import json
import unicodedata
from typing import Any, Mapping


GENESIS: str = "GENESIS"


def normalize_key(s: str) -> str:
    return unicodedata.normalize("NFC", s)


def canonical_bytes(line: Mapping[str, Any]) -> bytes:
    return json.dumps(
        line,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")


def line_hash(prev_hash: str, line: Mapping[str, Any]) -> str:
    stripped: dict[str, Any] = {}
    for k, v in line.items():
        if k == "hash" or k == "prev_hash":
            continue
        stripped[k] = v
    payload = (prev_hash + "|" + canonical_bytes(stripped).decode("utf-8")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

from __future__ import annotations

import os
import tempfile
from pathlib import Path
from typing import Iterable, List


def read_lines(path: Path | str) -> List[bytes]:
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(str(p))
    raw = p.read_bytes()
    if raw == b"":
        return []
    lines = raw.split(b"\n")
    if lines and lines[-1] == b"":
        lines = lines[:-1]
    return lines


def write_atomic(path: Path | str, lines: Iterable[bytes]) -> None:
    p = Path(path)
    parent = p.parent
    parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(
        prefix=".ledgerlock.",
        suffix=".tmp",
        dir=str(parent),
    )
    try:
        with os.fdopen(fd, "wb") as f:
            for line in lines:
                if not line.endswith(b"\n"):
                    f.write(line + b"\n")
                else:
                    f.write(line)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, str(p))
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise
